package io.github.ningpp.compat;

import java.util.Locale;

/**
 * Stub for System.Threading.Thread (generated by CSharpToJava converter).
 * Provides getCurrentCulture()/setCurrentCulture() used in C# thread-locale patterns.
 */
public class ThreadHelper {

    private final ThreadStart action;
    private static final ThreadHelper INSTANCE = new ThreadHelper();

    /** Mirrors Thread.CurrentThread (returns a ThreadHelper proxy). */
    public static ThreadHelper currentThread() { return INSTANCE; }

    /** Mirrors Thread.CurrentThread.CurrentCulture getter. */
    public CultureInfo getCurrentCulture() { return CultureInfo.getCurrentCulture(); }

    /** Mirrors Thread.CurrentThread.CurrentUICulture getter. */
    public CultureInfo getCurrentUICulture() { return CultureInfo.getCurrentUICulture(); }

    /** Mirrors Thread.CurrentThread.CurrentCulture setter with CultureInfo. */
    public void setCurrentCulture(CultureInfo culture) { CultureInfo.setCurrentCulture(culture); }

    /** Mirrors Thread.CurrentThread.CurrentUICulture setter with CultureInfo. */
    public void setCurrentUICulture(CultureInfo culture) { CultureInfo.setCurrentUICulture(culture); }

    /** Mirrors Thread.CurrentThread.CurrentCulture setter with Locale. */
    public void setCurrentCulture(Locale locale) { Locale.setDefault(locale); }

    /** Mirrors Thread.CurrentThread.CurrentCulture setter with Object (type-erased). */
    public void setCurrentCulture(Object culture) { /* no-op */ }

    /** Thread name (stub). */
    public String getName() { return java.lang.Thread.currentThread().getName(); }

    /** No-op join (stub). */
    public void join() throws InterruptedException { }

    /** Start (stub — not a real Thread). */
    /** Singleton instance holder. */

    private ThreadHelper() { this(null); }
    public ThreadHelper(ThreadStart action) {
        this.action = action;
    }

    public void start() {
        if (action != null) {
            new java.lang.Thread(action::run).start();
        }
    }

    /** Mirrors C# Thread.MemoryBarrier() using VarHandle.fullFence */
    public static void memoryBarrier() {
        java.lang.invoke.VarHandle.fullFence();
    }

    /** Mirrors C# Thread.Sleep(int millisecondsTimeout) */
    public static void sleep(int millisecondsTimeout) {
        try {
            java.lang.Thread.sleep(millisecondsTimeout);
        } catch (InterruptedException e) {
            java.lang.Thread.currentThread().interrupt();
        }
    }

    /** Mirrors C# Thread.Sleep(long millisecondsTimeout) */
    public static void sleep(long millisecondsTimeout) {
        try {
            java.lang.Thread.sleep(millisecondsTimeout);
        } catch (InterruptedException e) {
            java.lang.Thread.currentThread().interrupt();
        }
    }

    /** Mirrors C# Thread.Sleep(TimeSpan timeout) */
    public static void sleep(java.time.Duration timeout) {
        try {
            java.lang.Thread.sleep(timeout.toMillis());
        } catch (InterruptedException e) {
            java.lang.Thread.currentThread().interrupt();
        }
    }
}
